function normalized(model,calibration){if(model.userData.stageProp)return model;const profile=productProfile(model);if(profile){if(model.userData.physicalSize&&!calibration)return model;return createSizedModel(model,profile,calibration)}model.updateMatrixWorld(true);const bounds=new T.Box3().setFromObject(model);if(bounds.isEmpty())throw new Error('模型没有可显示的几何体');const size=bounds.getSize(new T.Vector3()),max=Math.max(size.x,size.y,size.z);if(!Number.isFinite(max)||max===0)throw new Error('模型尺寸无效');const inner=new T.Group();inner.add(model);inner.scale.setScalar(2.7/max);inner.updateMatrixWorld(true);const b=new T.Box3().setFromObject(inner),center=b.getCenter(new T.Vector3());inner.position.set(-center.x,-b.min.y,-center.z);const parent=new T.Group();parent.add(inner);return parent}
