function switchProjection(kind){const target=controls.target.clone(),pos=camera.position.clone(),aspect=stage.clientWidth/Math.max(1,stage.clientHeight);const distance=pos.distanceTo(target);if(kind==='orthographic'){camera=new T.OrthographicCamera(-4*aspect,4*aspect,4,-4,.05,3000);camera.zoom=4/Math.max(1,distance*Math.tan(T.MathUtils.degToRad(38)/2))}else{camera=new T.PerspectiveCamera(38,aspect,.05,3000);camera.setFocalLength(+$('#lens').value)}camera.position.copy(pos);camera.lookAt(target);camera.updateProjectionMatrix();setupControls(target);resize();syncCamera()}
