async function dbPut(value){await new Promise((resolve,reject)=>{const tx=db.transaction('projects','readwrite');tx.objectStore('projects').put(value,'last');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});const response=await fetch('/api/project',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(value)});if(!response.ok)throw new Error('布景已保存在浏览器，但应用文件夹备份失败，请检查磁盘空间。')}
