async function loadData(d){if(d?.format!=='form-product-studio'||d.version!==1||!d.objects?.object)throw new Error('这不是受支持的布景文件');const images=d.objects.images||[];for(const image of images){const urls=Array.isArray(image.url)?image.url:[image.url];for(const url of urls)if(typeof url==='string'&&!url.startsWith('data:image/'))throw new Error('布景文件包含外部图片，请使用工作台保存的完整本地文件')}
const loaded=await new T.ObjectLoader().parseAsync(d.objects);if(loaded.children.length>30)throw new Error('布景对象超过 30 个');gizmo.detach();objects.clear();while(loaded.children.length)objects.add(loaded.children[0]);let migrated=0;for(const o of items()){o.userData.uid ||=crypto.randomUUID();if(migrateProductSize(o))migrated++;if(migrateGeneratedMaterials(o))migrated++}sceneTheme=structuredClone(d.sceneTheme||{id:null,baseline:null});syncTheme();select(items()[0]||null);restoreSettings(migrateSurfaceSettings(d.settings,d.surfaceVersion),d.camera);record();if(migrated)scheduleSave()}
