$('#open-project').onclick=()=>$('#project-file').click();$('#project-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;await busy(async()=>{if(file.size>100*1024*1024)throw new Error('布景文件请控制在 100 MB 内');await loadData(JSON.parse(await file.text()));scheduleSave();say('已打开布景：'+file.name)});e.target.value=''};
