async function commitGenerated(result){const id=result.metadata?.generationId;let root=id&&items().find(o=>o.userData.generationId===id);if(root)select(root);else root=add(result.model,result.name,result.kind,result.metadata);if(id){clearTimeout(saveTimer);if(!db)db=await openDb();await dbPut(data());$('#save-state').textContent='已自动保存 · 浏览器与应用文件夹';await acknowledgeGeneration(id)}return root}
async function resumePending(retry=false){try{const result=await resumeGeneration(say,retry);if(result){await commitGenerated(result);fit(true);say('新品已生成并保存，可自由摆放、旋转与调光')}}catch(e){say(e.message)}}
