async function performImport(files){$('#import-notice').hidden=true;await busy(async()=>{let successes=0;const errors=[];for(const file of files){try{if(items().length>=30)throw new Error('场景最多30个对象，请先移除一个再添加');if(file.size>80*1024*1024)throw new Error('文件超过 80 MB');const ext=file.name.split('.').pop().toLowerCase();let model,kind='导入三维模型';if(ext==='glb'){const manager=new T.LoadingManager();manager.setURLModifier(url=>{if(url.startsWith('blob:')||url.startsWith('data:'))return url;throw new Error('GLB 需内嵌全部纹理，不支持外部资源')});const gltf=await new GLTFLoader(manager).parseAsync(await file.arrayBuffer(),'');model=gltf.scene;if(!model)throw new Error('未找到可显示场景')}else if(ext==='obj'){model=new OBJLoader().parse(await file.text());model.traverse(n=>{if(n.isMesh)n.material=new T.MeshStandardMaterial({color:'#c7c5ba',roughness:.5})});kind='OBJ 几何模型 · 默认材质'}else if(['png','jpg','jpeg','webp'].includes(ext)){$('#loading').hidden=true;const input=await requestProductInfo({source:await fileData(file),name:file.name});if(!input)continue;const result=await createDirectProduct(input.source,input.name,renderer,say,input.description);await commitGenerated(result);syncObject();fit(true);successes++;continue;}else throw new Error('支持 GLB、OBJ、PNG、JPG、WEBP');add(model,file.name.replace(/\.[^.]+$/,''),kind);successes++}catch(e){errors.push(file.name+'：'+e.message)}}if(errors.length){$('#import-notice-text').textContent=errors.join('；');$('#import-notice').hidden=false}say(errors.length?(successes?'已载入 '+successes+' 个产品。':'')+errors.join('；'):(successes?'已在场景中生成 '+successes+' 个产品，可直接摆放、旋转和调光':'未添加产品'))})}
async function addTextProduct(){const input=await requestProductInfo();if(!input)return;const run=()=>busy(async()=>{if(items().length>=30)throw new Error('场景最多30个对象，请先移除一个再添加');const result=await createDirectProduct(input.source,input.name,renderer,say,input.description);await commitGenerated(result);syncObject();fit(true);say('新品已生成并保存，可自由摆放、旋转与调光')});importQueue=importQueue.then(run,run);}
