async function exportPng(){try{await groundSurface.ready()}catch(e){say(e.message);return}const size=+$('#export-size').value,old=renderer.getSize(new T.Vector2()),ratio=renderer.getPixelRatio(),bg=scene.background,floorVisible=floor.visible,gridVisible=grid.visible,boxVisible=box.visible,gizmoVisible=gizmo.visible;try{const aspect=old.x/old.y;renderer.setPixelRatio(1);renderer.setSize(aspect>=1?size:Math.round(size*aspect),aspect>=1?Math.round(size/aspect):size,false);if($('#transparent').checked){scene.background=null;floor.visible=false;grid.visible=false}box.visible=false;gizmo.visible=false;renderer.render(scene,camera);const url=renderer.domElement.toDataURL('image/png'),binary=atob(url.split(',')[1]),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);download(new Blob([bytes],{type:'image/png'}),'FORM-产品布景.png');say('已导出 PNG，保留当前相机与光影')}catch(e){say('导出失败：'+e.message)}finally{scene.background=bg;floor.visible=floorVisible;grid.visible=gridVisible;box.visible=boxVisible;gizmo.visible=gizmoVisible;renderer.setPixelRatio(ratio);renderer.setSize(old.x,old.y,false);renderer.render(scene,camera)}}$('#export').onclick=$('#export-2').onclick=exportPng;
const raycaster=new T.Raycaster(),ndc=new T.Vector2(),plane=new T.Plane(),hitPoint=new T.Vector3(),offset=new T.Vector3();let pointerDrag=null;
function ray(e){const r=renderer.domElement.getBoundingClientRect();ndc.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);raycaster.setFromCamera(ndc,camera)}
renderer.domElement.addEventListener('pointerdown',e=>{if(e.button!==0||gizmo.axis||gizmo.dragging)return;ray(e);const found=raycaster.intersectObjects(items().filter(o=>o.visible),true)[0];if(!found)return;let root=found.object;while(root.parent!==objects)root=root.parent;select(root);if(currentTool==='translate'||currentTool==='rotate'){controls.enabled=false;plane.setFromNormalAndCoplanarPoint(camera.getWorldDirection(new T.Vector3()),root.position);if(raycaster.ray.intersectPlane(plane,hitPoint))offset.copy(root.position).sub(hitPoint);pointerDrag={x:e.clientX,y:e.clientY,object:root};renderer.domElement.setPointerCapture(e.pointerId)}});
renderer.domElement.addEventListener('pointermove',e=>{if(!pointerDrag||gizmo.dragging)return;const d=pointerDrag;if(currentTool==='translate'){ray(e);if(raycaster.ray.intersectPlane(plane,hitPoint))d.object.position.copy(hitPoint).add(offset)}else if(currentTool==='rotate'){d.object.rotation.y+=(e.clientX-d.x)*.01;d.object.rotation.x+=(e.clientY-d.y)*.01}d.x=e.clientX;d.y=e.clientY;syncObject();box.update()});
