window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)||$('#help').open)return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();restoreHistory(historyIndex+(e.shiftKey?1:-1));return}const tools={w:'translate',e:'rotate',r:'scale',q:'orbit'};if(tools[e.key.toLowerCase()])setTool(tools[e.key.toLowerCase()]);if(e.key.toLowerCase()==='f')fit();if(e.key==='Escape')setTool('orbit');if(selected&&e.key.startsWith('Arrow')&&currentTool!=='orbit'){e.preventDefault();const delta=e.shiftKey?.5:.1;if(currentTool==='rotate'){if(e.key==='ArrowLeft')selected.rotation.y-=.1;if(e.key==='ArrowRight')selected.rotation.y+=.1;if(e.key==='ArrowUp')selected.rotation.x-=.1;if(e.key==='ArrowDown')selected.rotation.x+=.1}else{if(e.key==='ArrowLeft')selected.position.x-=delta;if(e.key==='ArrowRight')selected.position.x+=delta;if(e.key==='ArrowUp')selected.position.y+=delta;if(e.key==='ArrowDown')selected.position.y-=delta}syncObject();record();scheduleSave()}});
function resize(){const w=stage.clientWidth,h=stage.clientHeight;if(!w||!h)return;renderer.setSize(w,h,false);const aspect=w/h;if(camera.isPerspectiveCamera)camera.aspect=aspect;else{camera.left=-4*aspect;camera.right=4*aspect}camera.updateProjectionMatrix()}new ResizeObserver(resize).observe(stage);
