function updateShadows(){
 const bounds=new T.Box3();items().filter(o=>o.visible).forEach(o=>bounds.expandByObject(o));if(bounds.isEmpty())return;
 const center=bounds.getCenter(new T.Vector3()),radius=T.MathUtils.clamp(bounds.getSize(new T.Vector3()).length()*.65,5,100);
 const angle=T.MathUtils.degToRad(+$('#key-angle').value),height=T.MathUtils.degToRad(+$('#key-height').value);
 key.target.position.copy(center);key.position.copy(center).addScaledVector(new T.Vector3(Math.sin(angle)*Math.cos(height),Math.sin(height),Math.cos(angle)*Math.cos(height)),radius*2+10);
 Object.assign(key.shadow.camera,{left:-radius,right:radius,top:radius,bottom:-radius,far:radius*4+40});key.shadow.camera.updateProjectionMatrix();
}
